  TipsType_31003_Desc = {
    Text = "กุญแจเงินรับรู้ถึงวิกฤตการณ์ที่ร้ายแรง ต้องการเปิดใช้งานร่างกายจิตวิญญาณฉุกเฉินหรือไม่?\n(การฟื้นคืนชีพจะใช้ร่างกายจิตวิญญาณฉุกเฉิน 1 ครั้ง ร่างกายจิตวิญญาณฉุกเฉินจะได้รับ 1 ครั้งโดยอัตโนมัติทุกวันเวลา 9 โมงเช้า ปัจจุบันจำนวนครั้งที่เหลือ：{s1})\n<Blue:(การฟื้นคืนชีพครั้งแรกไม่ใช้ร่างกายจิตวิญญาณฉุกเฉิน)>"
