  TipsType_31004_Desc = {
    Text = "กุญแจเงินรับรู้ถึงวิกฤตการณ์ร้ายแรง จะเปิดใช้งานร่างกายจิตวิญญาณฉุกเฉินหรือไม่?\n(การฟื้นคืนชีพจะใช้ร่างกายจิตวิญญาณฉุกเฉิน 1 ครั้ง ร่างกายจิตวิญญาณฉุกเฉินจะได้รับ 1 ครั้งโดยอัตโนมัติทุกวันเวลา 9 โมงเช้า จำนวนครั้งที่เหลือปัจจุบัน：{s1})\n<Blue:(การฟื้นคืนชีพครั้งแรกไม่ใช้ร่างกายจิตวิญญาณฉุกเฉิน)>"
