  TipsType_40001_Desc = {
    Text = "เมื่อชีวิตลดลงถึง 0 การสอบสวนจะสิ้นสุดลง。"
  },
  TipsType_40001_Title = {Text = "HP"},
  TipsType_40002_Desc = {
    Text = "การเคลื่อนที่ในแผนที่และเหตุการณ์การสอบสวนจะสร้างความกดดันทางจิตใจ ความกดดันที่สะสมจะทำให้ผู้พิทักษ์ได้รับอาการ \n ทุกครั้งที่เคลื่อนที่ 1 ช่อง ความกดดันจะเพิ่มขึ้น 10 คะแนน เมื่อความกดดันเต็ม 100 คะแนน จะได้รับ 1 อาการ \n เมื่อความกดดันถึง 500 คะแนน หลังจากนั้นทุกครั้งที่เคลื่อนที่ 1 ช่อง จะลดพลังชีวิต 10%。"
  },
  TipsType_40002_Title = {
    Text = "ความเครียด"
  },
  TipsType_40003_Desc = {
    Text = "ระดับการมอบหมายที่สูงขึ้น ความยากของภารกิจจะสูงขึ้น รางวัลที่ได้รับจากการมอบหมายก็จะเพิ่มขึ้นตามด้วย。"
  },
  TipsType_40003_Title = {
    Text = "ระดับการมอบหมาย"
  },
  TipsType_40004_Desc = {
    Text = "สำเนาชั่วคราวของการ์ดคำสั่งใบแรกที่เล่นในแต่ละรอบจะเข้าสู่มิติพิเศษ。\nเมื่อมิติพิเศษถึงขีดจำกัด จะได้รับเทิร์นอัลตร้าเพิ่มเติม 1 ครั้งและเก็บรักษาโล่。\nผลความชำนาญดินแดน：เมื่อเริ่มต้นรอบ มีโอกาสที่จะนำการ์ด「แรงบัลดาลใจ」 1 ใบเข้ามาในมือ。"
  },
  TipsType_40004_Title = {
    Text = "มิติพิเศษ"
  },
  TipsType_40005_Desc = {
    Text = "ผู้พิทักษ์สามารถเพิ่มระดับของตนเองได้ผ่านการสอบสวน การฝึกระหว่างฉาก และความท้าทายอื่น ๆ อีกมากมาย โหมดการเล่นเพิ่มเติมจะค่อย ๆ ถูกปลดล็อกเมื่อระดับของผู้พิทักษ์เพิ่มขึ้น。"
  },
  TipsType_40005_Title = {
    Text = "ระดับ"
  },
  TipsType_40006_Desc = {
    Text = "การเล่นการ์ดคำสั่งต้องใช้พลังการคำนวณ ในตอนจบเทิร์นจะไม่เก็บรักษาพลังการคำนวณที่เหลืออยู่ และในตอนเริ่มต้นเทิร์นจะทำให้พลังการคำนวณกลับคืนสู่ขีดสูงสุด。"
