  TipsType_40008_Desc = {
    Text = "สามารถใช้ได้เมื่อเผชิญกับวิกฤตการณ์ร้ายแรงในระหว่างการต่อสู้ ทุกครั้งที่ใช้จะต้องเสีย 1 ชิ้น ทำให้ผู้พิทักษ์มีพลังชีวิตและอาลีมัสของผู้ปลุกตื่นฟื้นฟูถึงขีดสูงสุด และจะได้รับ 1 ชิ้นโดยอัตโนมัติทุกวันเวลา 9 โมงเช้า。"
